"""Build the pupil–teacher dataset from the immutable bilingual NSO snapshot.

Run --register once to add a pending registry entry. Excel is generated by the
companion build_pupil_teacher_excel.mjs using the emitted wide JSON payload.
"""
import csv
import hashlib
import itertools
import json
import math
import shutil
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SITE = ROOT / 'data.mn'
SLUG = 'pupil-teacher-ratio'
TABLE = 'DT_NSO_2002_015V1.px'
VERSION = ROOT / 'tools/versions' / SLUG / 'v1'
RAW = VERSION / 'raw'
SEP = ' / '


def dump(path, obj):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, ensure_ascii=False, indent=2) + '\n')


def source_url(lang):
    return f'https://data.1212.mn/pxweb/{lang}/NSO/NSO__Education%2C%20health__General%20educational%20schools/{TABLE}/'


def load_source(lang):
    meta = json.loads((RAW / f'{lang}-metadata.json').read_text())
    data = json.loads((RAW / f'{lang}-data.json').read_text())
    variables = meta['variables']
    assert data['id'] == [v['code'] for v in variables]
    assert data['size'] == [2, 28, 19]
    for v in variables:
        assert data['dimension'][v['code']]['category']['index'] == {c: i for i, c in enumerate(v['values'])}
    labels = [dict(zip(v['values'], [s.strip() for s in v['valueTexts']])) for v in variables]
    assert sorted(map(int, labels[2].values())) == list(range(2007, 2026))
    values = data['value']
    if isinstance(values, dict):
        values = [values.get(str(i)) for i in range(1064)]
    assert len(values) == 1064
    assert all(isinstance(v, (float, int)) and math.isfinite(v) and v > 0 for v in values)
    cells = dict(zip(itertools.product(*(v['values'] for v in variables)), values))
    # The regional and city Ulaanbaatar entries must agree before dropping one.
    assert all(cells[level, '5', year] == cells[level, '511', year]
               for level in labels[0] for year in labels[2])
    return labels, cells


def main():
    manifest = json.loads((RAW / 'manifest.json').read_text())
    for name, digest in manifest['files'].items():
        assert hashlib.sha256((RAW / name).read_bytes()).hexdigest() == digest, name
    sources = {lang: load_source(lang) for lang in ('en', 'mn')}
    assert sources['en'][1] == sources['mn'][1], 'Bilingual values differ'
    en_labels = sources['en'][0]
    place_codes = ['0'] + sorted((c for c in en_labels[1] if len(c) == 3), key=en_labels[1].get)
    assert len(place_codes) == 23
    year_codes = sorted(en_labels[2], key=lambda c: int(en_labels[2][c]))
    ceiling = math.ceil(max(sources['en'][1].values()) / 5) * 5
    payload = {}
    for lang, (labels, cells) in sources.items():
        en = lang == 'en'
        year, series, value = ('year', 'series', 'pupils_per_teacher') if en else ('он', 'үзүүлэлт', 'нэг_багшид_ногдох_сурагч')
        levels = {'0': 'All levels' if en else 'Бүх түвшин', '1': 'Primary' if en else 'Бага боловсрол'}
        places = {c: labels[1][c] for c in place_codes}
        places['0'] = 'National average' if en else 'Улсын дундаж'
        records = [[int(labels[2][y]), levels[level] + SEP + places[p], cells[level, p, y]]
                   for y in year_codes for level in ('0', '1') for p in place_codes]
        assert len(records) == 874
        csvpath = SITE / f'public/datasets/{SLUG}-{lang}.csv'
        with csvpath.open('w', encoding='utf-8', newline='') as f:
            w = csv.writer(f, lineterminator='\n')
            w.writerow([year, series, value])
            w.writerows(records)
        shutil.copy2(csvpath, VERSION / f'data-{lang}.csv')
        categories = sorted({r[1] for r in records})
        indexed = {(r[0], r[1]): r[2] for r in records}
        payload[lang] = {'sheet': 'English' if en else 'Монгол', 'columns': [year, *categories],
                         'rows': [[y, *[indexed[y, c] for c in categories]] for y in range(2007, 2026)],
                         'source': source_url(lang)}
        j = lambda x: json.dumps(x, ensure_ascii=False)
        base = {'$schema': 'https://vega.github.io/schema/vega-lite/v5.json',
                'data': {'url': f'/datasets/{SLUG}-{lang}.csv', 'format': {'type': 'csv', 'parse': {year: 'number', value: 'number'}}},
                'config': {'axis': {'labelFontSize': 14, 'titleFontSize': 16, 'labelColor': '#64748b', 'titleColor': '#334155'},
                           'legend': {'labelFontSize': 13, 'titleFontSize': 14}, 'view': {'stroke': 'transparent'}}}
        decode = [{'calculate': f'split(datum[{j(series)}], " / ")[0]', 'as': 'level'},
                  {'calculate': f'split(datum[{j(series)}], " / ")[1]', 'as': 'place'}]
        lev_param = {'name': 'educationLevel', 'value': levels['1'], 'bind': {'input': 'select', 'options': [levels['1'], levels['0']], 'name': 'Education level: ' if en else 'Боловсролын түвшин: '}}
        units = 'Pupils per teacher' if en else 'Нэг багшид ногдох сурагч'
        ytitle = 'Year' if en else 'Он'
        place_title = 'Location' if en else 'Аймаг, нийслэл'
        tooltip = [{'field': 'place', 'type': 'nominal', 'title': place_title},
                   {'field': year, 'type': 'quantitative', 'format': 'd', 'title': ytitle},
                   {'field': 'level', 'type': 'nominal', 'title': 'Level' if en else 'Түвшин'},
                   {'field': value, 'type': 'quantitative', 'format': '.1f', 'title': units}]
        groups = ['Western', 'Khangai', 'Central', 'Eastern', 'Ulaanbaatar'] if en else ['Баруун бүс', 'Хангайн бүс', 'Төвийн бүс', 'Зүүн бүс', 'Улаанбаатар']
        group_expr = ' : '.join(f'indexof({j([places[c] for c in place_codes if c.startswith(str(i)) and c != "0"])}, datum.place) >= 0 ? {j(groups[i-1])}' for i in range(1, 5)) + ' : ' + j(groups[4])
        national = places['0']
        rank = {**base, 'description': ('Pupils per teacher by aimag and Ulaanbaatar, 2007–2025. Primary and all general-school levels. The dashed line is the official national ratio.' if en else 'Нэг багшид ногдох сурагчийн тоо, аймаг, нийслэлээр, 2007–2025. Бага боловсрол болон бүх түвшин. Тасархай шугам нь улсын дундаж.'),
                'params': [lev_param, {'name': 'selectedYear', 'value': 2025, 'bind': {'input': 'select', 'options': list(range(2025, 2006, -1)), 'name': ytitle + ': '}}],
                'transform': decode + [{'filter': f'datum.level === educationLevel && datum[{j(year)}] === selectedYear'}, {'calculate': group_expr, 'as': 'macroregion'}],
                'encoding': {'y': {'field': 'place', 'type': 'nominal', 'title': None, 'sort': {'field': value, 'op': 'max', 'order': 'descending'}, 'axis': {'labelLimit': 140}},
                             'x': {'field': value, 'type': 'quantitative', 'title': units, 'stack': None, 'scale': {'domain': [0, ceiling], 'nice': False}, 'axis': {'format': '.0f', 'tickCount': 5}}},
                'layer': [
                    {'transform': [{'filter': f'datum.place !== {j(national)}'}], 'mark': {'type': 'bar', 'cornerRadiusEnd': 2},
                     'encoding': {'color': {'field': 'macroregion', 'type': 'nominal', 'title': None, 'scale': {'domain': groups, 'range': ['#4e79a7', '#59a14f', '#f28e2b', '#b07aa1', '#e15759']}, 'legend': {'orient': 'top', 'rowPadding': 8}}, 'tooltip': tooltip}},
                    {'transform': [{'filter': f'datum.place !== {j(national)}'}], 'mark': {'type': 'text', 'align': 'left', 'dx': 5, 'fontSize': 11, 'color': '#334155'}, 'encoding': {'text': {'field': value, 'type': 'quantitative', 'format': '.1f'}, 'tooltip': tooltip}},
                    {'transform': [{'filter': f'datum.place === {j(national)}'}], 'mark': {'type': 'rule', 'strokeDash': [5, 4], 'color': '#64748b', 'strokeWidth': 2},
                     'encoding': {'y': {'value': 0}, 'y2': {'value': {'expr': 'height'}}, 'tooltip': tooltip}}
                ]}
        dump(SITE / f'public/charts/{SLUG}-{lang}.json', rank)
        slots = ['Location 1', 'Location 2', 'National average'] if en else ['Аймаг, нийслэл 1', 'Аймаг, нийслэл 2', 'Улсын дундаж']
        options = [places[c] for c in place_codes if c != '0']
        none = 'None' if en else 'Сонгохгүй'
        trend = {**base, 'description': ('Compare annual pupil–teacher ratios for two locations and the official national average, 2007–2025.' if en else 'Хоёр аймаг, нийслэлийн сурагч-багшийн харьцааг улсын дундажтай харьцуулах, 2007–2025.'),
                 'params': [lev_param,
                            {'name': 'locationOne', 'value': places['262'], 'bind': {'input': 'select', 'options': options, 'name': slots[0] + ': '}},
                            {'name': 'locationTwo', 'value': places['511'], 'bind': {'input': 'select', 'options': [none, *options], 'name': slots[1] + ': '}}],
                 'transform': decode + [{'filter': f'datum.level === educationLevel && (datum.place === locationOne || datum.place === locationTwo || datum.place === {j(national)})'},
                                        {'calculate': f'datum.place === {j(national)} ? {j(slots[2])} : datum.place === locationOne ? {j(slots[0])} : {j(slots[1])}', 'as': 'comparison'}],
                 'mark': {'type': 'line', 'strokeWidth': 2.5, 'point': {'filled': True, 'size': 25}},
                 'encoding': {'x': {'field': year, 'type': 'quantitative', 'title': ytitle, 'scale': {'domain': [2007, 2025], 'zero': False, 'nice': False}, 'axis': {'format': 'd', 'values': [2007, 2011, 2015, 2019, 2023, 2025], 'grid': False}},
                              'y': {'field': value, 'type': 'quantitative', 'title': units, 'scale': {'domain': [0, ceiling], 'nice': False}, 'axis': {'tickCount': 5}},
                              'color': {'field': 'comparison', 'type': 'nominal', 'title': None, 'scale': {'domain': slots, 'range': ['#2563eb', '#e07b16', '#64748b']}, 'legend': {'orient': 'top', 'rowPadding': 8}},
                              'strokeDash': {'condition': {'test': f'datum.place === {j(national)}', 'value': [6, 4]}, 'value': [1, 0]}, 'tooltip': tooltip}}
        # Separate nearest-point hover layer follows the site's chart standard.
        line = trend.pop('mark')
        dash = trend['encoding'].pop('strokeDash')
        trend['encoding']['y']['axis']['format'] = '.0f'
        trend['layer'] = [
            {'mark': line, 'encoding': {'strokeDash': dash}},
            {'params': [{'name': 'hover', 'select': {'type': 'point', 'nearest': True, 'on': 'pointerover', 'clear': 'pointerout'}}],
             'mark': {'type': 'point', 'filled': True, 'size': 100},
             'encoding': {'opacity': {'condition': {'param': 'hover', 'empty': False, 'value': 1}, 'value': 0}, 'tooltip': tooltip}}
        ]
        dump(SITE / f'public/charts/{SLUG}-trend-{lang}.json', trend)
        title = 'Pupils per Teacher in Mongolia by Aimag (2007–2025)' if en else 'Нэг багшид ногдох сурагчийн тоо, аймаг, нийслэлээр (2007–2025)'
        excerpt = ('Compare school staffing across Mongolia’s 21 aimags and Ulaanbaatar. In 2025, the primary-school ratio was 35.8 in Orkhon, 31.2 in Ulaanbaatar and 29.7 nationally.' if en else 'Монгол Улсын 21 аймаг, Улаанбаатарын сурагч-багшийн харьцаа. 2025 онд бага боловсролын нэг багшид Орхонд 35.8, Улаанбаатарт 31.2, улсын хэмжээнд 29.7 сурагч ногдож байв.')
        xlsx = SITE / f'public/datasets/{SLUG}-{lang}.xlsx'
        front = {'title': title, 'publishDate': '2026-11-01', 'excerpt': excerpt, 'category': 'Education' if en else 'Боловсрол',
                 'tags': ['mongolia', 'education', 'teachers', 'schools'] if en else ['монгол', 'боловсрол', 'багш', 'сургууль'],
                 'keywords': ['pupil teacher ratio', 'primary education', 'aimag', 'school staffing'] if en else ['сурагч багшийн харьцаа', 'бага боловсрол', 'аймаг', 'нэг багшид ногдох сурагч'],
                 'author': 'Data.mn', 'dataVersion': 1, 'dataDate': '2025-12-31', 'excelLanguage': 'page',
                 'dataFiles': [{'path': f'/datasets/{SLUG}-{lang}.csv', 'format': 'csv', 'size': f'{csvpath.stat().st_size / 1024:.1f} KB', 'description': 'Download all data (CSV)' if en else 'CSV татах (бүх өгөгдөл)'},
                               {'path': f'/datasets/{SLUG}-{lang}.xlsx', 'format': 'xlsx', 'size': f'{xlsx.stat().st_size / 1024:.1f} KB' if xlsx.exists() else '12 KB', 'description': 'Open in Excel' if en else 'Excel татах'}],
                 'source': {'name': 'National Statistics Office of Mongolia' if en else 'Үндэсний статистикийн хороо', 'url': source_url(lang), 'tableId': TABLE}}
        method = ('Pupils per teacher is the average number of pupils for each teacher at the selected education level. Primary and all-level ratios use their respective pupil and teacher populations. This measure is not class size and does not by itself measure teaching quality.\n\nThe source is the Ministry of Education, published by NSO. NSO’s definition describes pupils per teacher, although its web metadata displays “%”. Values are retained unchanged and shown as pupils per teacher, not percentages.\n\nYears retain the annual labels published by NSO. The definition refers to a school year. For context, the Ministry’s 2025–2026 totals of 819,907 pupils and 39,126 teachers give 21.0 pupils per teacher after rounding, matching NSO’s 2025 all-level national value. Earlier source years have not been independently mapped to school-year spans.\n\nNSO cites its education-statistics methodology dated 16 December 2013. The table does not establish that definitions and coverage are unchanged throughout 2007–2025. Historical values are displayed as published, with no interpolation or adjustment.\n\nDownloads contain 874 observations: 19 years, two education levels and 23 locations (21 aimags, Ulaanbaatar and the national average). The overlapping macroregion aggregates are excluded; the city-level Ulaanbaatar entry is retained once. The national average is the official source value, not an average of aimag ratios.\n\nCSV uses one observation per row. Its series label combines education level and location with “ / ”. Excel has one row per year and one column per level/location combination. Chart selections do not limit downloads.' if en else
                  'Нэг багшид ногдох сурагчийн тоо нь сонгосон боловсролын түвшний сурагч-багшийн дундаж харьцаа юм. Бага боловсрол болон бүх түвшний харьцааг тухайн түвшний сурагч, багшийн тоогоор тооцно. Энэ нь анги дүүргэлт биш бөгөөд сургалтын чанарыг дангаараа хэмжихгүй.\n\nӨгөгдлийг Боловсролын яамнаас авч, ҮСХ нийтэлдэг. ҮСХ-ны тодорхойлолтод нэг багшид ногдох сурагчдын дундаж тоо гэсэн боловч цахим хуудасны хэмжих нэгжид “%” гэж бичсэн. Утгыг өөрчлөлгүй хадгалж, хувиар бус нэг багшид ногдох сурагчийн тоогоор харуулав.\n\nОны тэмдэглэгээг ҮСХ-ны нийтэлснээр хадгалсан. Тодорхойлолт нь хичээлийн жилд хамаарна. Боловсролын яамны 2025–2026 оны 819,907 сурагч, 39,126 багшийн тооноос тооцвол нэг багшид 21.0 сурагч ногдож, ҮСХ-ны 2025 оны бүх түвшний улсын дүнтэй таарна. Өмнөх он бүрийг хичээлийн жилийн хугацаатай тусад нь тулган баталгаажуулаагүй.\n\nҮСХ-ны эх сурвалжид 2013 оны 12 дугаар сарын 16-ны боловсролын статистикийн аргачлалыг дурдсан. 2007–2025 оны турш тодорхойлолт, хамрах хүрээ өөрчлөгдөөгүйг энэ хүснэгт дангаараа батлахгүй. Түүхэн утгуудыг нийтэлснээр нь, нөхөлт болон засваргүй харуулав.\n\nТатах файлуудад 19 он, боловсролын хоёр түвшин, 23 байршлын (21 аймаг, Улаанбаатар, улсын дундаж) нийт 874 утга орсон. Давхардсан бүсийн нэгтгэсэн дүнг хасаж, Улаанбаатарыг нийслэлийн түвшинд нэг удаа оруулав. Улсын дундаж нь аймгуудын харьцааны энгийн дундаж биш, эх сурвалжийн албан ёсны утга юм.\n\nCSV файлын нэг мөр нэг утга агуулна. Үзүүлэлтийн нэр нь боловсролын түвшин, байршлыг “ / ” тэмдэгтээр холбоно. Excel-д онууд мөрөөр, түвшин ба байршлын хослолууд баганаар байрлана. Графикийн сонголт татах файлын хамрах хүрээг хязгаарлахгүй.')
        body = '---\n' + '\n'.join(f'{k}: {v if k in ("publishDate", "dataDate") else j(v)}' for k, v in front.items())
        body += '\nmethodology: |\n' + '\n'.join('  ' + s if s else '' for s in method.split('\n')) + '\n---\n\n'
        body += "import PupilTeacherChart from '~/components/ui/PupilTeacherChart.astro';\n\n"
        ranktitle = 'Compare aimags and Ulaanbaatar' if en else 'Аймаг, Улаанбаатарыг харьцуулах'
        caption = 'Choose an education level and year. Colors show geographic regions; the dashed line marks the national average. Hover for exact values.' if en else 'Боловсролын түвшин, оноо сонгоно уу. Өнгө нь бүсийг, тасархай шугам нь улсын дунджийг илэрхийлнэ. Дээр нь заахад утга харагдана.'
        body += f'<PupilTeacherChart spec="/charts/{SLUG}-{lang}.json" title="{ranktitle}" caption="{caption}" />\n\n'
        note = 'Pupils per teacher measures school staffing. It is not the number of pupils in a classroom.' if en else 'Энэ үзүүлэлт нь сурагч-багшийн харьцаа бөгөөд нэг ангийн сурагчдын тоо биш.'
        body += f'<div className="text-sm text-slate-600 dark:text-slate-400">{note}</div>\n\n'
        trendtitle = 'Compare changes over time' if en else 'Олон жилийн өөрчлөлтийг харьцуулах'
        trendcaption = 'Choose up to two locations and compare with the national average. Blue is location 1, orange is location 2. Selecting the same location twice shows it once.' if en else 'Хоёр хүртэлх аймаг, нийслэлийг улсын дундажтай харьцуулна уу. Цэнхэр нь эхний, улбар шар нь хоёр дахь сонголт. Ижил байршлыг хоёр сонговол нэг удаа харуулна.'
        body += f'<h2>{trendtitle}</h2>\n\n<PupilTeacherChart spec="/charts/{SLUG}-trend-{lang}.json" title="{units}, 2007–2025" caption="{trendcaption}" aspectRatio={{0.65}} />\n\n'
        body += ('<div className="text-sm">School-year context: <a href="https://moe.gov.mn/post/170077">Ministry of Education, 2025–2026 statistics</a>.</div>\n' if en else '<div className="text-sm">Хичээлийн жилийн тайлбар: <a href="https://moe.gov.mn/post/170077">Боловсролын яамны 2025–2026 оны статистик</a>.</div>\n')
        (SITE / f'src/data/data/{lang}/{SLUG}.mdx').write_text(body)
    dump(ROOT / 'tools/temp/pupil-teacher-excel.json', payload)
    dump(VERSION / 'validation.json', {'source_hashes_verified': True, 'bilingual_cells_equal': True, 'source_observations_per_language': 1064,
                                      'published_observations_per_language': 874, 'years': [2007, 2025], 'missing_values': 0, 'ulaanbaatar_duplicate_equal': True})
    if '--register' in sys.argv:
        sys.path.insert(0, str(ROOT / 'tools'))
        from registry.registry import Registry, Dataset, Version
        registry = Registry()
        if registry.get_dataset(SLUG) is None:
            registry.add_dataset(Dataset(id=SLUG, source_id='nso-1212', name_en='Pupils per teacher by aimag', name_mn='Нэг багшид ногдох сурагчийн тоо, аймаг, нийслэлээр',
                                         category_en='Education', category_mn='Боловсрол', definition_path=f'tools/sources/nso-1212/datasets/{SLUG}.md', source_ref=TABLE,
                                         source_path=manifest['source_path'], status='pending', auto_update=False, auto_publish=False,
                                         tags=['mongolia', 'education', 'teachers', 'schools'], source_metadata={'unit': 'pupils per teacher', 'frequency': 'annual', 'years': [2007, 2025], 'locations': 23, 'education_levels': 2}))
            registry.update_dataset(SLUG, current_version=1, data_file=f'data.mn/public/datasets/{SLUG}-en.csv', mdx_file_en=f'data.mn/src/data/data/en/{SLUG}.mdx',
                                    mdx_file_mn=f'data.mn/src/data/data/mn/{SLUG}.mdx', chart_spec=f'data.mn/public/charts/{SLUG}-en.json', data_as_of='2025-12-31',
                                    source_updated_at=manifest['source_updated_at'], last_fetched_at=manifest['retrieved_at'], canonical_slug=SLUG)
            registry.add_version(Version(id=0, dataset_id=SLUG, version=1, data_hash=hashlib.sha256((VERSION / 'data-en.csv').read_bytes()).hexdigest(),
                                         data_path=f'tools/versions/{SLUG}/v1/data-en.csv', row_count=874, column_count=3, change_type='initial',
                                         change_summary='Annual pupil–teacher ratios, primary and all levels, 21 aimags, Ulaanbaatar and national average.',
                                         source_updated_at=manifest['source_updated_at'], source_raw_files=[f'tools/versions/{SLUG}/v1/raw/{n}' for n in manifest['files']]))
    print('Built 874 aligned observations per language, four chart specs, two pages, and Excel input. Axis maximum:', ceiling)


if __name__ == '__main__':
    main()
